import "server-only";
import { cookies } from "next/headers";
import { encode, decode } from "next-auth/jwt";
import { google } from "googleapis";
import { db } from "@/lib/db";
import { auth } from "@/auth";
import { freshAuthentication } from "./auth-freshness";
const cookieName = "mailloop-admin-challenge";
export async function startAdminChallenge(userId: string) {
  const secret = process.env.AUTH_SECRET;
  if (!secret) throw new Error("ADMIN_UNAVAILABLE");
  const value = await encode({
    secret,
    salt: cookieName,
    maxAge: 300,
    token: { userId, startedAt: Math.floor(Date.now() / 1000) },
  });
  (await cookies()).set(cookieName, value, {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "lax",
    path: "/",
    maxAge: 300,
  });
}
export async function verifyAdminReauth(idToken: string | undefined) {
  if (!idToken || !process.env.AUTH_SECRET || !process.env.GOOGLE_CLIENT_ID)
    throw new Error("ADMIN_REAUTH_DENIED");
  const jar = await cookies();
  const challenge = await decode({
    secret: process.env.AUTH_SECRET,
    salt: cookieName,
    token: jar.get(cookieName)?.value,
  });
  const session = await auth();
  if (
    !session?.user.id ||
    challenge?.userId !== session.user.id ||
    typeof challenge.startedAt !== "number" ||
    challenge.startedAt * 1000 > Date.now() ||
    Date.now() - challenge.startedAt * 1000 > 300000
  )
    throw new Error("ADMIN_REAUTH_DENIED");
  // Verify the signed ID token, never userinfo, JWT iat, or the local clock alone.
  const ticket = await new google.auth.OAuth2(
    process.env.GOOGLE_CLIENT_ID,
  ).verifyIdToken({ idToken, audience: process.env.GOOGLE_CLIENT_ID });
  const claims = ticket.getPayload() as ReturnType<typeof ticket.getPayload> & {
    auth_time?: unknown;
  };
  if (
    !claims?.sub ||
    claims.email_verified !== true ||
    !freshAuthentication(claims.auth_time) ||
    Number(claims.auth_time) < challenge.startedAt - 60
  )
    throw new Error("ADMIN_REAUTH_DENIED");
  const user = await db.user.findUnique({
    where: { id: session.user.id },
    select: {
      id: true,
      googleId: true,
      isAdmin: true,
      isSuspended: true,
      deletionRequestedAt: true,
    },
  });
  if (
    !user?.isAdmin ||
    user.isSuspended ||
    user.deletionRequestedAt ||
    user.googleId !== claims.sub
  )
    throw new Error("ADMIN_REAUTH_DENIED");
  return { userId: user.id, authTime: claims.auth_time as number };
}
export async function clearAdminChallenge() {
  (await cookies()).delete(cookieName);
}
